install(Authentication) {
    basic("auth") { validate { cred -> if (valid(cred)) UserIdPrincipal(cred.name) else null } }
}
routing {
    authenticate("auth") {                 // protects exactly the routes inside this block
        get("/orders") {
            val user = call.principal<UserIdPrincipal>() ?: return@get call.respond(HttpStatusCode.Forbidden)
            call.respond(listOrders(user))
        }
    }
    get("/health") { call.respondText("ok") }   // explicit public route, reviewable
}
